    "factor_updates": [
      {
        "factor": "Lamag margin (BN majority 5,681)",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "A large majority reduces the plausibility of overturn via petition; calibrates the probability strongly downward."
      },
      {
        "factor": "Active petitions against Sabah seats (Sindumin, Pintasan)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Documented petition activity introduces a nonzero risk channel, preventing a flat-zero assessment."
      },
      {
        "factor": "Historical rarity of overturns in Malaysian elections",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Past overturns are uncommon, supporting a low base-rate probability."
      },
      {
        "factor": "Time window to May 1, 2026 for petition hearings",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Limited time reduces the chance of a ruling reversing the result before the deadline."
      },
      {
        "factor": "Absence of public reports of a Lamag overturn as of early 2026",
        "direction": "down",
        "magnitude": "weak",
        "rationale": "No known overturns to date lowers perceived risk, though it is not proof of safety."
      }
    ],
    "synthesis_rationale": "Weights reflect a Bayesian updating sequence: start with a cautious baseline from the reference class; apply a strong downward update for the large Lamag margin, with modest upward pressure from ongoing Sabah petition activity. Moderate downward pressure from historical rarity and the short hearing window, plus weak downward signal from the lack of overturns to date, yield a low posterior of roughly 1%. Correlations between petitions and overturn outcomes are acknowledged but not assumed perfectly independent; calibration emphasizes a conservative, low-risk conclusion with a narrow range."
  }
}

